-- Some default env vars.
hl.env("VK_ICD_FILENAMES", "/usr/share/vulkan/icd.d/radeon_icd.x86_64.json")
hl.env("WLR_RENDERER", "vulkan")
hl.env("XCURSOR_THEME", "Qogir")
hl.env("XCURSOR_SIZE", "24")
hl.env("WLR_NO_HARDWARE_CURSORS", "1")
hl.env("GTK_THEME", "Dracula")
hl.env("HYPRCURSOR_THEME", "rose-pine-hyprcursor")
hl.env("HYPRCURSOR_SIZE", "24")

hl.device({
    name = "logitech-usb-receiver-mouse",
    natural_scroll = true,
    scroll_method = "on_button_down",
    scroll_button = 276,
})

-- For all categories, see https://wiki.hyprland.org/Configuring/Variables/

hl.curve("myBezier", { type = "bezier", points = { { 0.05, 0.9 }, { 0.1, 1.05 } } })
hl.animation({
    leaf = "windows",
    enabled = true,
    speed = 7,
    bezier = "myBezier",
})
hl.animation({
    leaf = "windowsOut",
    enabled = true,
    speed = 7,
    bezier = "default",
    style = "popin 80%",
})
hl.animation({
    leaf = "border",
    enabled = true,
    speed = 10,
    bezier = "default",
})
hl.animation({
    leaf = "borderangle",
    enabled = true,
    speed = 8,
    bezier = "default",
})
hl.animation({
    leaf = "fade",
    enabled = true,
    speed = 7,
    bezier = "default",
})
hl.animation({
    leaf = "workspaces",
    enabled = true,
    speed = 6,
    bezier = "default",
})

hl.device({
    name = "epic-mouse-v1",
    sensitivity = -0.5,
})

hl.workspace_rule({
    workspace = "1",
    monitor = "eDP-1",
    persistent = true,
})

hl.workspace_rule({
    workspace = "2",
    monitor = "eDP-1",
    persistent = true,
})

hl.workspace_rule({
    workspace = "3",
    monitor = "eDP-1",
    persistent = true,
})

hl.workspace_rule({
    workspace = "4",
    monitor = "eDP-1",
    persistent = true,
})

hl.workspace_rule({
    workspace = "w[tv1]",
    gaps_out = 0,
    gaps_in = 0,
})

hl.workspace_rule({
    workspace = "f[1]",
    gaps_out = 0,
    gaps_in = 0,
})

hl.window_rule({
    match = {
        float = 0,
        workspace = "w[tv1]",
    },
    border_size = 0,
    rounding = 0,
})

hl.window_rule({
    match = {
        float = 0,
        workspace = "f[1]",
    },
    border_size = 0,
    rounding = 0,
})

hl.window_rule({
    name = "opacity",
    match = {
        focus = false,
    },
    opacity = 0.5,
})

hl.window_rule({
    name = "gimp",
    match = {
        class = "^(gimp)$",
        focus = false,
    },
    opacity = 1,
})

hl.window_rule({
    name = "siril",
    match = {
        class = "^(siril)$",
        focus = false,
    },
    opacity = 1,
})

hl.window_rule({
    name = "dunst opacity",
    match = {
        class = "^(Dunst)$",
    },
    opacity = 0.8,
})

-- TODO: manual review — top-level key 'blurls = rofi' has no enclosing section
hl.layer_rule({
    name  = "blur-rofi",
    match = { namespace = "^rofi$" },
    blur  = true,
})

local mainMod = "SUPER"

hl.bind(mainMod .. " + Q", hl.dsp.exec_cmd("kitty"))
