hl.on("hyprland.start", function()
    hl.exec_cmd("/usr/local/bin/hypr")
    hl.exec_cmd("systemctl --user import-environment DISPLAY WAYLAND_DISPLAY XDG_CURRENT_DESKTOP")
    hl.exec_cmd("dbus-update-activation-environment --systemd DISPLAY WAYLAND_DISPLAY XDG_CURRENT_DESKTOP")
    hl.exec_cmd("~.config/hypr/bin/xdg.sh")
    hl.exec_cmd("waybar & ~/bin/set_wallpaper.sh -l ~/bin/wallpapers.txt")
    hl.exec_cmd("hyprpaper &")
    hl.exec_cmd("export QT_QPA_PLATFORMTHEME=qt5ct")
    hl.exec_cmd("/usr/lib/polkit-kde-authentication-agent-1 &")
    hl.exec_cmd("dunst &")
    hl.exec_cmd("nm-applet &")
    hl.exec_cmd("blueman-applet &")
    hl.exec_cmd("hypridle &")
    hl.exec_cmd("swayosd-server &")
    hl.exec_cmd("~/.config/hypr/bin/updatenotif.sh &")
    hl.exec_cmd("wl-paste -t text --watch clipman store --no-persist &")
    hl.exec_cmd("udiskie --no-automount --no-notify --tray")
    hl.exec_cmd("~/bin/songinfo.sh &")
    hl.exec_cmd("warp-taskbar &")
end)

